function formatBytes(bytes: number) {
  if (!bytes) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  return `${(bytes / Math.pow(1024, index)).toFixed(index ? 1 : 0)} ${units[index]}`;
}

function fileExt(name: string) { return name.split('.').pop()?.toUpperCase() || 'FILE'; }
function isImage(file: File) { return file.type.startsWith('image/') || /\.(jpe?g|png|webp)$/i.test(file.name); }
function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const image = new Image();
    image.onload = () => {
      URL.revokeObjectURL(url);
      if (!image.naturalWidth || !image.naturalHeight) {
        reject(new Error('This image has no readable dimensions.'));
      } else if (image.naturalWidth > 12000 || image.naturalHeight > 12000) {
        reject(new Error('This image is larger than the supported 12,000 px edge limit.'));
      } else {
        resolve(image);
      }
    };
    image.onerror = () => { URL.revokeObjectURL(url); reject(new Error('This image could not be decoded. It may be corrupt or unsupported.')); };
    image.src = url;
  });
}
function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url; anchor.download = filename; anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function canvasBlob(canvas: HTMLCanvasElement, type: string, quality?: number): Promise<Blob> {
  return new Promise((resolve, reject) => canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('The browser could not create an output file.')), type, quality));
}
function fitRect(sw: number, sh: number, dw: number, dh: number, mode: 'crop' | 'fit') {
  const scale = mode === 'crop' ? Math.max(dw / sw, dh / sh) : Math.min(dw / sw, dh / sh);
  const w = sw * scale, h = sh * scale;
  return { x: (dw - w) / 2, y: (dh - h) / 2, w, h };
}

function Seo({ title, description, path = '', schema }: { title: string; description: string; path?: string; schema?: object }) {
  useEffect(() => {
    document.title = `${title} | FileFit Pro`;
    document.querySelector('meta[name="description"]')?.setAttribute('content', description);
    let canonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
    if (!canonical) { canonical = document.createElement('link'); canonical.rel = 'canonical'; document.head.appendChild(canonical); }
    canonical.href = `${window.location.origin}${path || window.location.pathname}`;
    document.querySelector('meta[property="og:title"]')?.setAttribute('content', title);
    document.querySelector('meta[property="og:description"]')?.setAttribute('content', description);
    document.querySelector('meta[name="twitter:title"]')?.setAttribute('content', title);
    document.querySelector('meta[name="twitter:description"]')?.setAttribute('content', description);
    const old = document.getElementById('route-schema'); old?.remove();
    if (schema) { const script = document.createElement('script'); script.id = 'route-schema'; script.type = 'application/ld+json'; script.textContent = JSON.stringify(schema); document.head.appendChild(script); }
    return () => { document.getElementById('route-schema')?.remove(); };
  }, [title, description, path, schema]);
  return null;
}

